      "options": [
        {
          "id": "A",
          "text": "Active message count growing steadily"
        },
        {
          "id": "B",
          "text": "Server errors"
        },
        {
          "id": "C",
          "text": "Successful requests"
        },
        {
          "id": "D",
          "text": "Namespace CPU"
        }
      ],
